-- Expanded Psionics Handbook source-backed D&D 3.5 psionics rules catalog.
-- XPH is the revised 3.5 psionics authority and is intended to supersede overlapping D&D 3.0 Psionics Handbook procedures.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('xph-3.5','expanded-psionics-handbook-3-5','Expanded Psionics Handbook','XPH','Wizards of the Coast','dnd','3.5',
        'D&D 3.5 revised psionics sourcebook: psionic races, classes, feats, powers, prestige classes, items, monsters, and core psionics procedures.',NULL,1,0,NULL);

WITH desired(slug,name,source_page,category,kind,is_variant,default_enabled,summary,tags,mechanics) AS (VALUES
  ('xph-manifesting-powers','Manifesting Powers','53-54','psionics','rule',0,1,'A psionic character selects a power known that can be manifested, pays its power-point cost from the daily reserve, concentrates as required, and applies the power when manifestation succeeds.','["psionics","manifesting","power-points"]','{"prepare_ahead":false,"must_know_power":true,"pays_power_points":true}'),
  ('xph-power-point-cost-by-level','Power Point Cost by Power Level','63','psionics','table',0,1,'Base power-point cost is determined by power level according to the standard 1st-through-9th-level progression.','["psionics","power-points","power-level"]','{"cost_by_level":{"1":1,"2":3,"3":5,"4":7,"5":9,"6":11,"7":13,"8":15,"9":17}}'),
  ('xph-power-point-limit','Power Point Limit','54,63','psionics','rule',0,1,'The total number of power points spent on a single manifestation for any reason cannot exceed the manifester level unless a specific rule says otherwise.','["psionics","power-points","augmentation","manifester-level"]','{"maximum_points_spent":"manifester level"}'),
  ('xph-augmentation','Augmenting Powers','63','psionics','rule',0,1,'A power with an Augment entry can gain listed additional effects by spending extra power points when it is manifested, subject to the manifester-level power-point limit.','["psionics","augmentation","power-points"]','{"timing":"when manifested","subject_to_power_point_limit":true}'),
  ('xph-manifester-level','Manifester Level','54','psionics','rule',0,1,'A power''s level-dependent variables normally use the manifester''s psionic class level, and a manifester can voluntarily use a lower manifester level if it remains high enough to manifest the power and pays the required cost.','["psionics","manifester-level"]','{"default":"psionic class level","can_voluntarily_lower":true}'),
  ('xph-concentration-injury','Concentration while Manifesting: Injury','54','psionics','rule',0,1,'Damage taken during manifestation can disrupt a power; the Concentration DC is 10 + damage taken + power level.','["psionics","concentration","damage"]','{"dc":"10 + damage taken + power level"}'),
  ('xph-concentration-continuous-damage','Concentration while Manifesting: Continuous Damage','54','psionics','rule',0,1,'Continuous damage during manifestation uses a Concentration DC of 10 + half the most recent continuous damage + power level.','["psionics","concentration","damage"]','{"dc":"10 + half continuous damage + power level"}'),
  ('xph-manifest-defensively','Manifesting Powers on the Defensive','54','psionics','rule',0,1,'A manifester can avoid provoking attacks of opportunity by succeeding on a Concentration check with DC 15 + power level; failure loses the power points without manifesting the power.','["psionics","concentration","attacks-of-opportunity"]','{"dc":"15 + power level","success":"no attack of opportunity","failure":"power points lost and power fails"}'),
  ('xph-concentration-grappled','Manifesting while Grappling or Pinned','54','psionics','rule',0,1,'Manifesting normally while grappled or pinned requires a Concentration check with DC 20 + power level; failure loses the power.','["psionics","concentration","grapple"]','{"dc":"20 + power level"}'),
  ('xph-power-failure','Power Failure','54-55','psionics','rule',0,1,'If a power''s required targeting or other manifestation conditions cannot be met, or concentration is broken, the manifestation fails and the spent power points are wasted.','["psionics","manifesting","failure"]','{"spent_power_points_refunded":false}'),
  ('xph-power-attacks','Powers Considered Attacks','55','psionics','rule',0,1,'Offensive combat actions and powers that deal damage or that opponents can resist with saving throws are generally treated as attacks; powers such as astral construct that create something which later attacks are not themselves attacks.','["psionics","attacks","powers"]','{}'),
  ('xph-psionics-magic-transparency','Psionics-Magic Transparency','55','psionics','rule',0,1,'By default, psionic powers and magic interact as equivalent effect systems: spell resistance applies to powers, power resistance applies to spells, dispels cross systems, detect magic detects psionics, and dead-magic areas also suppress psionics.','["psionics","magic","transparency","spell-resistance","power-resistance"]','{"default":true,"spell_resistance_applies_to_powers":true,"power_resistance_applies_to_spells":true,"cross_dispel":true,"detect_magic_detects_psionics":true,"dead_magic_suppresses_psionics":true}'),
  ('xph-stacking-same-bonus-type','Psionic and Magical Bonus Stacking','55-56','psionics','rule',0,1,'Bonuses or penalties of the same type generally do not stack even when one comes from a power and another from a spell; differently typed bonuses generally stack.','["psionics","magic","stacking","bonuses"]','{"same_type_stacks":false,"different_types_stack":true}'),
  ('xph-same-effect-different-strengths','Same Effect in Different Strengths','56','psionics','rule',0,1,'When multiple copies of the same or very similar effect operate at different strengths, only the stronger effect normally applies while the weaker one continues to exist underneath it.','["psionics","stacking","effects"]','{"apply":"strongest"}'),
  ('xph-opposite-effects','Powers and Spells with Opposite Effects','56','psionics','rule',0,1,'Opposite power and spell effects apply their bonuses, penalties, or changes normally in order unless the specific effects state that they negate or counter one another.','["psionics","magic","effects"]','{}'),
  ('xph-instantaneous-effects-stack','Instantaneous Effects','56','psionics','rule',0,1,'Multiple instantaneous magical or psionic effects on the same target apply cumulatively; each effect is resolved independently.','["psionics","magic","instantaneous","stacking"]','{"cumulative":true}'),
  ('xph-power-displays','Power Displays','58-59','psionics','rule',0,1,'A manifested power can produce a secondary auditory, material, mental, olfactory, or visual display when its description specifies one; displays are separate from the primary mechanical effect.','["psionics","display","manifesting"]','{"display_types":["auditory","material","mental","olfactory","visual"]}'),
  ('xph-dispense-with-display','Dispense with Displays','58','psionics','rule',0,1,'A manifester can suppress all displays of a power by succeeding on a Concentration check with DC 15 + power level; failure still manifests the power normally with its display.','["psionics","display","concentration"]','{"dc":"15 + power level","failure":"power manifests with display"}'),
  ('xph-swift-action','Swift Actions','59','combat','rule',0,1,'A swift action can be used once per turn when a free action would normally be allowed; manifesting a quickened power or a power whose manifestation time is one swift action uses it and does not provoke attacks of opportunity.','["psionics","actions","swift"]','{"max_per_turn":1,"quickened_power":true,"swift_power_provokes_aoo":false}'),
  ('xph-immediate-action','Immediate Actions','59','combat','rule',0,1,'An immediate action can be used outside the user''s turn. On-turn use counts as that turn''s swift action; out-of-turn use prevents another immediate or swift action until after the next turn, and immediate actions cannot be used while flat-footed.','["psionics","actions","immediate","swift"]','{"usable_out_of_turn":true,"on_turn_counts_as_swift":true,"out_of_turn_consumes_next_swift":true,"usable_while_flat_footed":false}'),
  ('xph-power-range','Power Range Categories','59','psionics','table',0,1,'Powers use personal, touch, close, medium, long, or explicitly measured ranges; close, medium, and long ranges scale with manifester level.','["psionics","range","targeting"]','{"close":"25 ft + 5 ft per 2 manifester levels","medium":"100 ft + 10 ft per manifester level","long":"400 ft + 40 ft per manifester level"}'),
  ('xph-power-line-of-effect','Power Line of Effect','60-61','psionics','rule',0,1,'A manifester needs a clear line of effect to a target or to the point of origin of a power; solid barriers block line of effect unless a rule specifically provides otherwise.','["psionics","line-of-effect","targeting"]','{}'),
  ('xph-power-duration','Power Duration','61','psionics','rule',0,1,'Power duration can be timed, instantaneous, permanent, concentration-based, discharge-based, or dismissible; the duration entry controls how long the psionic effect persists.','["psionics","duration"]','{"duration_types":["timed","instantaneous","permanent","concentration","discharge","dismissible"]}'),
  ('xph-holding-touch-charge','Holding a Touch Power Charge','61','psionics','rule',0,1,'If a touch power is not discharged in the manifestation round, its charge can normally be held indefinitely; touching something with the charged hand discharges it, and manifesting another power dissipates the held charge.','["psionics","touch","charge"]','{"held_indefinitely":true,"manifest_another_power_dissipates":true}'),
  ('xph-power-save-dc','Power Saving Throw DC','62','psionics','rule',0,1,'The standard saving throw DC for a power is 10 + the power level applicable to the manifester''s class + the manifester''s key ability modifier.','["psionics","saving-throws","dc"]','{"formula":"10 + power level + key ability modifier"}'),
  ('xph-power-save-natural-rolls','Natural Rolls on Power Saving Throws','62','psionics','rule',0,1,'A natural 1 on a saving throw against a power always fails and a natural 20 always succeeds.','["psionics","saving-throws","natural-roll"]','{"natural_1":"automatic failure","natural_20":"automatic success"}'),
  ('xph-power-resistance','Power Resistance','62','psionics','rule',0,1,'When power resistance protects a target, the manifester makes a manifester-level check and must equal or exceed the target''s power resistance.','["psionics","power-resistance","manifester-level"]','{"check":"1d20 + manifester level","success":"result >= power resistance"}'),
  ('xph-daily-power-point-recovery','Daily Power Point Recovery','63-64','psionics','procedure',0,1,'To regain daily power points, a psionic character needs a clear mind and 8 hours of restful calm, including at least 1 hour immediately before recovery; recent manifestations in the previous 8 hours count against the refreshed daily limit.','["psionics","power-points","rest"]','{"rest_hours":8,"immediately_prior_rest_hours":1,"recent_manifesting_window_hours":8,"recovery_concentration_time":"1 full round"}'),
  ('xph-psionic-focus','Psionic Focus','37','psionics','subsystem',0,1,'A character with at least 1 power point available can gain psionic focus by meditating as a full-round action and succeeding on a DC 20 Concentration check. Focus remains until expended, consciousness is lost, sleep or trance begins, or the power-point reserve reaches 0.','["psionics","focus","concentration"]','{"minimum_power_points_available":1,"gain_action":"full-round","gain_concentration_dc":20,"ends_on":["expended","unconscious","sleep","trance","power point reserve 0"]}'),
  ('xph-expend-focus-concentration','Expend Psionic Focus for Concentration','37','psionics','rule',0,1,'A psionically focused character can expend focus on a Concentration check and treat the die result as 15 before adding modifiers.','["psionics","focus","concentration"]','{"treated_die_result":15}'),
  ('xph-saving-throw-d20-variant','Variant: Rolled Power Save DC','61','psionics','rule',1,0,'As an optional alternative to the fixed base 10 save DC, the manifester rolls d20 and sets the power''s save DC to that roll + power level + key ability modifier.','["psionics","variant","saving-throws","dc"]','{"formula":"d20 + power level + key ability modifier"}'),
  ('xph-psionics-are-different','Variant: Psionics Is Different','65-66','psionics','subsystem',1,0,'The optional non-transparency variant treats psionics and magic as separate forms of power, changing how resistance, dispelling, detection, antimagic, and equivalent protections interact.','["psionics","variant","magic","transparency"]','{"psionics_magic_transparency":false}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'xph-3.5-rule-' || d.slug, 'xph-3.5', d.source_page, d.slug, d.name, d.summary, d.summary,
  0,NULL,1,d.category,d.kind,d.is_variant,d.default_enabled,NULL,NULL,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.slug=d.slug AND r.owner_user_id IS NULL
);
